package com.xianyusmart.service;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.xianyusmart.context.*;
import com.xianyusmart.entity.SysUser;
import com.xianyusmart.mapper.SysUserMapper;
import com.xianyusmart.exception.BusinessException;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;import java.security.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PdcaProgressServiceTest {
 @TempDir Path dir;SysUserMapper users;PlatformPermissionService permissions;SysUser user;
 @BeforeEach void init()throws Exception{dir=dir.toRealPath();users=mock(SysUserMapper.class);permissions=mock(PlatformPermissionService.class);user=new SysUser();user.setId(7L);user.setTenantId(1L);user.setStatus(1);user.setRole("OPERATOR");user.setMemberRole("OWNER");when(users.selectById(7L)).thenReturn(user);when(permissions.hasPermission(user,PermissionCatalog.MENU_SETTINGS)).thenReturn(true);TenantContext.set(1L);UserContext.set(7L,"QA",1L);}
 @AfterEach void clear(){TenantContext.clear();UserContext.clear();}
 PdcaProgressService service(String tenants){return new PdcaProgressService(users,permissions,dir.toString(),tenants,1800);}
 void publish(ObjectNode snapshot)throws Exception{String rev=snapshot.get("revision").asText(),name="pdca-tenant-1-r"+rev+".json";byte[] payload=PdcaProgressSnapshotTest.bytes(snapshot);Files.write(dir.resolve(name),payload);var manifest=PdcaProgressSnapshotTest.JSON.createObjectNode();manifest.put("schemaVersion",1).put("tenantId",1).put("revision",rev).put("snapshotFile",name).put("snapshotSha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload))).put("sourceLedgerSha256","a".repeat(64)).putNull("previousRevision").putNull("previousSnapshotFile").putNull("previousSnapshotSha256");Files.write(dir.resolve("pdca-tenant-1-manifest.json"),PdcaProgressSnapshotTest.bytes(manifest));}
 @Test void defaultAndUnmappedTenantsHaveNoDemoOrCounts() {var s=new PdcaProgressService(users,permissions,"","1",1800);assertEquals("NOT_CONFIGURED",s.overview(null).get("reason"));assertFalse((Boolean)s.overview(null).get("snapshotAvailable"));assertEquals("NO_LEDGER_FOR_TENANT",service("").overview(null).get("reason"));}
 @Test void currentRolePermissionDisableAndAdminTenantCheckedEveryTime()throws Exception{publish(PdcaProgressSnapshotTest.sample());var s=service("1");assertTrue((Boolean)s.overview(null).get("snapshotAvailable"));user.setMemberRole("OPERATOR");assertEquals(403,assertThrows(BusinessException.class,()->s.overview(null)).getCode());user.setRole("ADMIN");user.setTenantId(2L);assertEquals(403,assertThrows(BusinessException.class,()->s.items(Map.of())).getCode());user.setTenantId(1L);user.setStatus(0);assertEquals(403,assertThrows(BusinessException.class,()->s.overview(null)).getCode());user.setStatus(1);when(permissions.hasPermission(user,PermissionCatalog.MENU_SETTINGS)).thenReturn(false);assertEquals(403,assertThrows(BusinessException.class,()->s.overview(null)).getCode());TenantContext.clear();UserContext.clear();assertEquals(401,assertThrows(BusinessException.class,()->s.overview(null)).getCode());}
 @Test void paginationRevisionChangeStalenessAndCountsStayHonest()throws Exception{var n=PdcaProgressSnapshotTest.sample();n.put("sourceObservedAt",java.time.Instant.now().minusSeconds(1900).toString());publish(n);var s=service("1");var overview=s.overview(null);assertTrue((Boolean)overview.get("stale"));assertFalse(overview.containsKey("percent"));assertEquals(1,((Map<?,?>)overview.get("counts")).get("registeredItems"));var page=s.items(Map.of("page","2","pageSize","1","knownRevision","1"));assertEquals(1,page.get("page"));assertTrue((Boolean)page.get("revisionChanged"));assertEquals(1,((List<?>)page.get("records")).size());assertEquals(0,s.items(Map.of("severity","P0")).get("total"));}
 @Test void keywordFindsOriginalRequirementAndBugIdsAcrossSourceTitles()throws Exception{var n=PdcaProgressSnapshotTest.sample();var first=(ObjectNode)n.get("items").get(0);first.put("originalId","OPS02").put("requirementId","OPS02");var second=first.deepCopy();second.put("key","item-"+"b".repeat(24)).put("sourceRef","src-other");n.withArray("sourceTitles").addObject().put("sourceId","src-other").put("safeTitle","另一来源");n.withArray("items").add(second);n.withObject("inventory").put("ledgerSourceRecordCount",2);publish(n);assertEquals(2,service("1").items(Map.of("keyword","OPS02")).get("total"));assertEquals(0,service("1").items(Map.of("keyword","PRD01")).get("total"));first.put("originalId","PRD01").put("requirementId","PRD01");publish(n);assertEquals(1,service("1").items(Map.of("keyword","PRD01")).get("total"));}
 @Test void corruptedAndSymlinkedPublicationNeverFallsBackToOldState()throws Exception{publish(PdcaProgressSnapshotTest.sample());var s=service("1");Path payload=dir.resolve("pdca-tenant-1-r9223372036854775808.json");Files.writeString(payload,"{}");var ex=assertThrows(BusinessException.class,()->s.overview(null));assertEquals(503,ex.getCode());assertFalse(ex.getMessage().contains(dir.toString()));Files.delete(payload);Files.createSymbolicLink(payload,dir.resolve("outside.json"));assertEquals(503,assertThrows(BusinessException.class,()->s.overview(null)).getCode());}
 @Test void sourceTenantMismatchDoesNotLeakCounts()throws Exception{var n=PdcaProgressSnapshotTest.sample();n.put("tenantId",2);publish(n);assertEquals(403,assertThrows(BusinessException.class,()->service("1").overview(null)).getCode());}
 @Test void unknownCommandsAndUnboundedQueriesRejectWithoutFileReads(){var s=service("1");for(Map<String,String> q:List.of(Map.of("path","/etc/passwd"),Map.of("tenant","2"),Map.of("command","anything"),Map.of("pageSize","51"),Map.of("keyword","x".repeat(101)),Map.of("type","task")))assertEquals(400,assertThrows(BusinessException.class,()->s.items(q)).getCode());}
 @Test void bugOriginalIdIsSearchableWithoutBeingInTitle()throws Exception{var n=PdcaProgressSnapshotTest.sample();var bug=((ObjectNode)n.get("items").get(0)).deepCopy();bug.remove(List.of("requirementId","implementationState","releaseState","blockerType"));bug.put("key","bug-"+"c".repeat(24)).put("originalId","C-R01-003").put("bugId","C-R01-003").put("recordKind","DEFECT").put("status","FIXED_PENDING_CHECK");n.withArray("bugs").add(bug);n.withObject("inventory").put("defectRecordCount",1);publish(n);assertEquals(1,service("1").items(Map.of("type","bug","keyword","C-R01-003")).get("total"));assertEquals(0,service("1").items(Map.of("type","requirement","keyword","C-R01-003")).get("total"));}
 @Test void unsupportedManifestAndMalformedPreviousAre503NotTenantDenial()throws Exception{publish(PdcaProgressSnapshotTest.sample());Path manifest=dir.resolve("pdca-tenant-1-manifest.json");var n=(ObjectNode)PdcaProgressSnapshotTest.JSON.readTree(Files.readAllBytes(manifest));n.put("schemaVersion",2);Files.write(manifest,PdcaProgressSnapshotTest.bytes(n));assertEquals(503,assertThrows(BusinessException.class,()->service("1").overview(null)).getCode());n.put("schemaVersion",1).put("previousSnapshotFile","unexpected.json");Files.write(manifest,PdcaProgressSnapshotTest.bytes(n));assertEquals(503,assertThrows(BusinessException.class,()->service("1").overview(null)).getCode());}
}
